def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "navigate_to_patient_room": And([
            self.room_has_contaminated_areas,
            Not(self.sterilized)
        ]),
        "deliver_supplies": And([
            self.room_has_contaminated_areas,
            Not(self.sterilized)
        ])
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
